import React, { useState, useCallback, useMemo } from 'react';
import styled from '@emotion/styled';
import { Layout, NavTree, ALL_PLACES, buildNavEntries, usePlaceRecents } from '@atlantis/shared';
import type { NavEntry, Place } from '@atlantis/shared';

const PLACE_BY_ID = new Map<string, Place>(ALL_PLACES.map((p) => [p.id, p]));
const DEFAULT_PLACE = ALL_PLACES.find((p) => p.id === 'lisbon') ?? ALL_PLACES[0];

const MapFrame = styled.iframe`
  flex: 1;
  width: 100%;
  border: none;
  display: block;
`;

function windyUrl(place: Place) {
  return (
    `https://embed.windy.com/embed.html` +
    `?type=map&location=coordinates` +
    `&metricRain=mm&metricTemp=°C&metricWind=km/h` +
    `&zoom=${place.zoom}` +
    `&overlay=wind` +
    `&product=ecmwf` +
    `&level=surface` +
    `&lat=${place.lat}&lon=${place.lng}`
  );
}

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [place, setPlace] = useState<Place>(DEFAULT_PLACE);
  const [activeId, setActiveId] = useState<string>(DEFAULT_PLACE.id);
  const { recent, addRecent } = usePlaceRecents('atlantis:weather:recent');

  const handleSelect = useCallback((entry: NavEntry) => {
    if (entry.id.startsWith('country-') || entry.id === '__recent__') return;
    const found = PLACE_BY_ID.get(entry.id);
    if (found) {
      setPlace(found);
      setActiveId(found.id);
      addRecent(found.id);
    }
  }, []);

  const navEntries = useMemo(() => buildNavEntries(recent), [recent]);

  const sidebar = <NavTree entries={navEntries} activeId={activeId} onSelect={handleSelect} />;

  return (
    <Layout title="Weather" sidebar={sidebar} activeId={activeId} topBarRight={topBarRight}>
      <MapFrame
        key={place.id}
        src={windyUrl(place)}
        title={`Weather near ${place.name}`}
        allowFullScreen
      />
    </Layout>
  );
}
